#!/usr/bin/env python3
"""Embed the licensed Carlito fallback font; run from any directory."""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
source = root / 'VastDevKit/lib/carlito/Carlito-Regular.ttf'
target = root / 'VastDevKit/src/ui/fonts/DefaultFont.h'
data = source.read_bytes()
lines = [
    '#ifndef _VAST_UI_FONT_DEFAULT_FONT_H_',
    '#define _VAST_UI_FONT_DEFAULT_FONT_H_',
    '',
    '// Generated by scripts/generate-default-font.py. Do not edit by hand.',
    '// Carlito Regular, SIL Open Font License 1.1; see lib/carlito/OFL.txt.',
    '',
    'unsigned char DefaultFontBytes[] = {',
]
lines.extend('    ' + ', '.join(f'0x{b:02x}' for b in data[i:i + 16]) + ','
             for i in range(0, len(data), 16))
lines.extend(['};', f'unsigned int DefaultFontLen = {len(data)};', '', '#endif', ''])
target.write_text('\n'.join(lines))
